/* Test database schema */

create table patient
(
    id                             int auto_increment primary key,
    letzte_information             date                 null,
    sterbedatum                    date                 null,
    sterbedatum_acc                varchar(10)          null,
    versicherungsnummer            varchar(50)          null,
    versicherungsnummer_gueltig_ab date                 null,
    geburtsort                     char(50)             null,
    geburtsland                    char(3)              null,
    patienten_id                   char(20)             null,
    pid_gesperrt                   tinyint(1) default 0 not null,
    familienangehoerigennummer     varchar(12)          null,
    krankenkassennummer            varchar(12)          null,
    kostentraegertyp               varchar(32)          null,
    quelleVitalstatus              varchar(64)          null,
    import_job                     int                  null,
    angelegt_am                    datetime             null,
    anmerkung                      text                 null,
    anmerkung_lkr                  text                 null,
    sid                            int                  null,
    guid                           binary(36)           null,
    revision                       int                  null,
    personenstamm                  int                  null,
    mpi_id                         int                  null,
    geschlecht                     char                 null,
    geburtsdatum                   date                 null,
    geburtsdatum_acc               varchar(10)          null,
    titel                          varchar(20)          null,
    namenzusatz                    varchar(30)          null,
    vorname                        varchar(100)         null,
    nachname                       varchar(100)         null,
    geburtsname                    varchar(50)          null,
    fruehere_namen                 varchar(50)          null,
    phonetik_vorname               varchar(255)         null,
    phonetik_nachname              varchar(255)         null,
    telefon                        varchar(50)          null,
    telefon2                       varchar(50)          null,
    email                          varchar(100)         null,
    staatsangehoerigkeit           varchar(3)           null,
    familienstand                  char                 null,
    staat_id                       char(3)              null,
    bundesland                     char(2)              null,
    ort                            char(50)             null,
    postleitzahl                   char(10)             null,
    strasse                        char(60)             null,
    hausnummer                     varchar(50)          null,
    adresszusatz                   varchar(255)         null,
    postfix                        char                 null,
    GKZ                            char(8)              null,
    nachsorgepassnr                varchar(50)          null,
    ahvnummer                      varchar(20)          null,
    referenznummer_vorgabe         varchar(50)          null,
    patienten_ids_vorher           varchar(500)         null,
    aktion_id                      int                  null,
    zusatzfelder                   text                 null,
    pseudonym                      varchar(36)          null,
    secretKey                      varchar(50)          null,
    zu_loeschen                    tinyint(1) default 0 not null,
    zugriff_gesperrt               tinyint(1) default 0 not null,
    namensvorsatz                  varchar(50)          null,
    organisationunit_id            int                  null,
    patienten_id2                  char(20)             null,
    crypto_key                     varchar(2048)        null,
    crypto_iv                      varchar(255)         null,
    crypto_chiffrat                mediumtext           null,
    crypto_key_id                  varchar(50)          null,
    dublette                       binary(36)           null,
    dublettenpruefung              datetime             null,
    bearbeitet_am                  datetime             null,
    beihilfestelle                 varchar(255)         null,
    crypto_timestamp               datetime             null
);

create table prozedur
(
    id                            int auto_increment primary key,
    patient_id                    int                  not null,
    beginndatum                   date                 null,
    beginnuhrzeit                 time                 null,
    beginnzeitpunkt_acc           varchar(10)          null,
    enddatum                      date                 null,
    enduhrzeit                    time                 null,
    text                          varchar(255)         null,
    hauptprozedur_id              int                  null,
    prozedurtyp                   int                  not null,
    data_form_id                  int                  not null,
    geloescht                     tinyint(1) default 0 not null,
    status                        int                  null,
    dokumentierende_fachabteilung int                  null,
    mpi_id                        int                  null,
    html_schnipsel_komprimiert    text                 null,
    html_schnipsel_detailiert     text                 null,
    data_form_entry_id            int                  null,
    filterkategorien              blob                 null,
    html_schnipsel_kalender       text                 null,
    import_job                    int                  null,
    status_zertifizierung         int        default 0 not null,
    status_dkg                    int        default 0 not null,
    status_eusoma                 int        default 0 not null,
    hat_dokumente                 tinyint(1)           not null,
    sid                           int                  null,
    guid                          binary(36)           null,
    revision                      int                  null,
    bearbeitung_status            int        default 0 not null,
    aktuelle_seite                int                  null,
    migriert                      tinyint(1) default 0 not null,
    mig_referenz_name             varchar(100)         null,
    mig_referenz_id               varchar(100)         null,
    mig_referenz_zusatz           blob                 null,
    mig_lkr_meldung               tinyint(1)           null,
    mig_lkr_meldung_id            varchar(100)         null,
    aktion_id                     int                  null,
    zuletzt_geaendert             bigint               null,
    bearbeiter                    varchar(255)         null,
    crypto_key                    varchar(2048)        null,
    crypto_iv                     varchar(255)         null,
    crypto_chiffrat               mediumtext           null,
    crypto_key_id                 varchar(50)          null,
    erstelldatum                  datetime             null,
    ersteller                     varchar(255)         null,
    cache_timestamp               bigint               null,
    idat_crypto_key               varchar(2048)        null,
    idat_crypto_iv                varchar(255)         null,
    idat_crypto_chiffrat          mediumtext           null,
    idat_crypto_key_id            varchar(50)          null,
    idat_crypto_timestamp         datetime             null
);

create table erkrankung_prozedur
(
    erkrankung_id int not null,
    prozedur_id   int not null
);

create table dk_mtb_anmeldung
(
    id                                     int auto_increment primary key,
    anmeldedatum                           date                    null,
    anmeldedatum_acc                       varchar(10)             null,
    anmeldender                            varchar(10)  default '' null,
    anmeldender_propcat_version            int                     null,
    anzahlvortherapien                     int                     null,
    behandlungbei                          varchar(255) default '' null,
    diagnose                               varchar(10)  default '' null,
    diagnose_propcat_version               int                     null,
    diagnosedatum                          date                    null,
    diagnosedatum_acc                      varchar(10)             null,
    ecog                                   varchar(64)  default '' null,
    ecog_propcat_version                   int                     null,
    einwilligung                           varchar(64)  default '' null,
    einwilligung_propcat_version           int                     null,
    empfehlung                             int                     null,
    fragestellung                          text                    null,
    grundnichtvorstellung                  varchar(255) default '' null,
    grundtherapieende                      varchar(64)  default '' null,
    grundtherapieende_propcat_version      int                     null,
    histologie                             varchar(10)  default '' null,
    histologie_propcat_version             int                     null,
    internextern                           varchar(64)  default '' null,
    internextern_propcat_version           int                     null,
    konferenzdatum                         date                    null,
    konferenzdatum_acc                     varchar(10)             null,
    kooperationspartner                    varchar(64)  default '' null,
    kooperationspartner_propcat_version    int                     null,
    leitliniengerecht                      varchar(64)  default '' null,
    leitliniengerecht_propcat_version      int                     null,
    leitliniengerechtgrund                 varchar(64)  default '' null,
    leitliniengerechtgrund_propcat_version int                     null,
    leitliniengerechtsonstig               text                    null,
    leitlinienstatus                       varchar(64)  default '' null,
    leitlinienstatus_propcat_version       int                     null,
    mtbtermin                              datetime                null,
    progressionsdatum                      date                    null,
    progressionsdatum_acc                  varchar(10)             null,
    tuko                                   int                     null,
    tumorkonferenz                         varchar(64)  default '' null,
    tumorkonferenz_propcat_version         int                     null,
    untersuchungen                         varchar(64)  default '' null,
    untersuchungen_propcat_version         int                     null,
    vorbefunde                             text                    null,
    whograd                                varchar(64)  default '' null,
    whograd_propcat_version                int                     null,
    aktuelletherapielinie                  int                     null,
    anderetumore                           text                    null,
    einsendenummer                         varchar(255) default '' null,
    erkrankung_guid                        varchar(255) default '' null,
    erkrankung_revision                    varchar(255) default '' null,
    erkrankung_sid                         varchar(255) default '' null,
    externandere                           varchar(255) default '' null,
    frueheretumore                         varchar(64)  default '' null,
    frueheretumore_propcat_version         int                     null,
    gesperrt                               tinyint(1)   default 0  null,
    letztetherapie                         text                    null,
    mig_referenz_tumor_id                  varchar(255) default '' null,
    pid_gesperrt                           varchar(255) default '' null,
    tumor_id                               varchar(255) default '' null,
    vorgestellt                            varchar(64)  default '' null,
    vorgestellt_propcat_version            int                     null
);

create table dk_mtb_empfehlung
(
    id                                 int auto_increment primary key,
    anmeldender                        varchar(10)  default '' null,
    anmeldender_propcat_version        int                     null,
    anmeldung                          int                     null,
    befund                             text                    null,
    diagnose                           varchar(10)  default '' null,
    diagnose_propcat_version           int                     null,
    diagnostik_propcat_version         int                     null,
    einsendenummer                     varchar(255) default '' null,
    empfehlung                         text                    null,
    histologie                         varchar(10)  default '' null,
    histologie_propcat_version         int                     null,
    mtbdatum                           date                    null,
    mtbdatum_acc                       varchar(10)             null,
    modellvorhaben                     varchar(64)  default '' null,
    modellvorhaben_propcat_version     int                     null,
    studieextern                       varchar(255) default '' null,
    studieintern                       varchar(64)  default '' null,
    studieintern_propcat_version       int                     null,
    studieinternextern                 varchar(64)  default '' null,
    studieinternextern_propcat_version int                     null,
    studiejanein                       varchar(64)  default '' null,
    studiejanein_propcat_version       int                     null,
    vorstellender                      varchar(10)  default '' null,
    vorstellender_propcat_version      int                     null,
    gespeichertvon                     varchar(10)  default '' null,
    gespeichertvon_propcat_version     int                     null,
    humangen_ber_begruendung           text                    null,
    humangen_beratung                  varchar(64)  default '' null,
    humangen_beratung_propcat_version  int                     null
);
